param([Parameter(Mandatory)][string]$PrivateKeyPath)
$ErrorActionPreference='Stop';$root=Split-Path $PSScriptRoot -Parent;Set-Location $root
$version=([xml](Get-Content .\Directory.Build.props -Raw)).Project.PropertyGroup.Version;$folder=Join-Path $root 'artifacts\release'
$rsa=[Security.Cryptography.RSA]::Create();$rsa.ImportFromPem([IO.File]::ReadAllText((Resolve-Path -LiteralPath $PrivateKeyPath)))
foreach($arch in @('x64','x86')){$name="DedsecTests-$version-Portable-$arch.zip";$file=Join-Path $folder $name;$m=[ordered]@{version=$version;url="https://github.com/Dedseckms/Dedsec-Tests/releases/download/v$version/$name";sha256=(Get-FileHash -LiteralPath $file -Algorithm SHA256).Hash.ToLowerInvariant();size=(Get-Item -LiteralPath $file).Length;architecture=$arch};$bytes=[Text.Encoding]::UTF8.GetBytes(($m|ConvertTo-Json));[IO.File]::WriteAllBytes((Join-Path $folder "update-$arch.json"),$bytes);[IO.File]::WriteAllBytes((Join-Path $folder "update-$arch.sig"),$rsa.SignData($bytes,[Security.Cryptography.HashAlgorithmName]::SHA256,[Security.Cryptography.RSASignaturePadding]::Pss))}
$rsa.Dispose();$lines=Get-ChildItem -LiteralPath $folder -File | Where-Object Name -ne 'SHA256SUMS.txt' | Sort-Object Name | ForEach-Object {"$((Get-FileHash -LiteralPath $_.FullName -Algorithm SHA256).Hash.ToLowerInvariant())  $($_.Name)"};[IO.File]::WriteAllLines((Join-Path $folder 'SHA256SUMS.txt'),[string[]]$lines,[Text.UTF8Encoding]::new($false))
